import express from 'express';
import { config } from './config/index.js';
import { createStore } from './store.js';
import { notesRouter } from './routes/notes.js';
import { adminRouter } from './routes/admin.js';

export function createApp(store = createStore()) {
  const app = express();
  app.disable('x-powered-by');
  app.use('/notes', notesRouter(store));
  app.use(adminRouter(store));
  app.use((err, req, res, next) => {
    console.error(err);
    res.status(500).json({ error: 'internal error' });
  });
  return app;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  createApp().listen(config.port, () => console.log(`notes-api listening on :${config.port}`));
}
// Central config, read once from the environment.
export const config = {
  port: Number(process.env.PORT ?? 3000),
  databaseUrl: process.env.DATABASE_URL ?? 'sqlite:./data/dev.db',
  sessionSecret: process.env.SESSION_SECRET ?? '',
  adminToken: process.env.ADMIN_TOKEN ?? '',
  stagingApiUrl: process.env.STAGING_API_URL ?? 'https://staging.notes.internal',
};
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createStore } from '../src/store.js';

test('adds and gets a note', () => {
  const store = createStore();
  const note = store.add({ title: 'groceries', body: 'milk' });
  assert.equal(store.get(note.id).title, 'groceries');
});

test('removes a note', () => {
  const store = createStore();
  const note = store.add({ title: 'temp' });
  assert.equal(store.remove(note.id), true);
  assert.equal(store.get(note.id), null);
  assert.equal(store.remove(note.id), false);
});

test('counts notes', () => {
  const store = createStore();
  store.add({ title: 'a' });
  store.add({ title: 'b' });
  assert.equal(store.count(), 2);
});

